introduction.codeBlock:
import { xalor } from '@bgskinner2/xalor';

// 1. Write clean, standard TypeScript types
export interface User {
  id: number;
  name: string;
  email?: string;
}

// 2. Map it to a string key identifier
xalor.register<'USER'>();

// 3. Narrow and guard data inline instantly
const data: unknown = { id: 101, name: 'Brennan' };

if (xalor.guard<'USER'>(data)) {
  console.log(data.name); // ✨ Fully typed automatically!
}

